package paymenttrace
import("context";"errors";"testing";"time")
type fakePort struct{rows []Record;err error};func(p fakePort)ReadTrace(context.Context,Query)([]Record,error){return append([]Record(nil),p.rows...),p.err}
func record(id string,o int64)Record{return Record{TenantID:"tenant-a",EventID:id,EventDigest:"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",AcknowledgementCursor:"cursor-1",ProjectionRevision:"projection-1",MigrationID:"0001",MigrationChecksum:"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",ResultCode:"accepted",Ordering:o,DurationMS:1}}
func TestTraceScopesBoundsAndOrdersDeterministically(t *testing.T){s:=Service{Port:fakePort{rows:[]Record{record("event-b",2),record("event-a",1)}}};got,err:=s.Trace(context.Background(),Query{TenantID:"tenant-a",Limit:2,Timeout:time.Second});if err!=nil||got[0].EventID!="event-a"{t.Fatalf("got %#v err %v",got,err)}}
func TestTraceFailsClosed(t *testing.T){s:=Service{Port:fakePort{rows:[]Record{record("event",1)}}};for _,q:=range []Query{{TenantID:"",Limit:1,Timeout:time.Second},{TenantID:"tenant-a",Limit:101,Timeout:time.Second}}{if _,err:=s.Trace(context.Background(),q);err==nil{t.Fatal("expected invalid query")}};s.Port=fakePort{err:errors.New("schema checksum mismatch")};if _,err:=s.Trace(context.Background(),Query{TenantID:"tenant-a",Limit:1,Timeout:time.Second});err==nil{t.Fatal("expected port failure")}}
